"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { AlertCircle, Loader2, CheckCircle, PlusCircle, FileText, X, Clock, ChefHat } from "lucide-react";
import Layout from "./Layout";

export default function ChefReportHistory() {
  const [reports, setReports] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [selectedReport, setSelectedReport] = useState(null);
  const [reportType, setReportType] = useState("problème repas");
  const [description, setDescription] = useState("");

  useEffect(() => {
    fetchReports();
  }, []);

  const fetchReports = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");
    const role = localStorage.getItem("role");
    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/reports/my-reports`, {
        headers: { Authorization: `Bearer ${token}`, Role: role },
      });
      setReports(response.data.data || []);
    } catch (err) {
      setError("Erreur lors de la récupération des rapports : " + (err.response?.data?.message || err.message));
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateReport = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    const token = localStorage.getItem("token");
    const role = localStorage.getItem("role");
    try {
      const response = await axios.post(
        `${process.env.REACT_APP_API_URL}/api/reports/submit`,
        { reportType, description },
        { headers: { Authorization: `Bearer ${token}`, Role: role } }
      );
      setSuccess("Rapport créé avec succès !");
      setIsModalOpen(false);
      setReportType("problème repas");
      setDescription("");
      fetchReports();
    } catch (err) {
      setError("Erreur lors de la création du rapport : " + (err.response?.data?.message || err.message));
    }
  };

  const openDetailModal = (report) => {
    setSelectedReport(report);
    setIsDetailModalOpen(true);
  };
  const closeDetailModal = () => setIsDetailModalOpen(false);

  return (
    <Layout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6 flex justify-between items-center">
            <div className="flex items-center">
              <div className="bg-white/10 p-3 rounded-full mr-4">
                <ChefHat className="h-8 w-8" />
              </div>
              <div>
                <h2 className="text-2xl font-bold tracking-tight">Historique des Rapports - Chef</h2>
                <p className="text-white/80 mt-1 text-sm">Vos rapports soumis</p>
              </div>
            </div>
            <button
              onClick={() => setIsModalOpen(true)}
              className="px-4 py-2 bg-[#00717F] hover:bg-[#00717F] rounded-md text-white font-medium flex items-center gap-2 transition-colors"
            >
              <PlusCircle className="h-5 w-5" />
              Créer un Rapport
            </button>
          </div>

          {(error || success) && (
            <div
              className={`p-4 m-4 rounded-r-md ${error ? "bg-red-50 border-l-4 border-red-500" : "bg-green-50 border-l-4 border-green-500"} flex items-center gap-3`}
            >
              {error ? (
                <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
              ) : (
                <CheckCircle className="h-5 w-5 text-green-500 flex-shrink-0" />
              )}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>{error || success}</p>
            </div>
          )}

          <div className="p-6">
            {isLoading ? (
              <div className="flex justify-center items-center h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                  <p className="text-[#00717F] text-sm font-medium">Chargement des rapports...</p>
                </div>
              </div>
            ) : reports.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-64 text-gray-500">
                <FileText className="h-12 w-12 text-gray-300 mb-3" />
                <p className="text-center">Aucun rapport soumis pour le moment.</p>
              </div>
            ) : (
              <ul className="space-y-4">
                {reports.map((report) => (
                  <li
                    key={report._id}
                    className="p-5 bg-gray-50 rounded-xl hover:bg-[#F5F6FA] transition-colors duration-150 cursor-pointer border border-transparent hover:border-[#C8A45D/30]/50 shadow-sm"
                    onClick={() => openDetailModal(report)}
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <div className="flex items-center mb-2">
                          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-100 text-amber-800 mr-2">
                            {report.reportType }
                          </span>
                          <span className="text-xs text-gray-400 flex items-center">
                            <Clock className="h-4 w-4 mr-1 text-gray-400" />
                            {new Date(report.createdAt).toLocaleDateString("fr-FR")}
                          </span>
                        </div>
                        <p className="text-sm text-gray-700 mb-2">{report.description}</p>

                      </div>
                      <div className="ml-4 flex-shrink-0">
                        <div className="h-8 w-8 rounded-full bg-[#F5F6FA] flex items-center justify-center">
                          <svg className="h-4 w-4 text-[#00717F]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                          </svg>
                        </div>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>

      {/* Creation Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center p-4">
          <div className="bg-white rounded-xl p-0 w-full max-w-md shadow-2xl animate-fadeIn overflow-hidden">
            <div className="bg-[#00717F] text-white p-4 flex justify-between items-center">
              <h3 className="text-xl font-semibold">Créer un Rapport - Le cuisinier</h3>
              <button onClick={() => setIsModalOpen(false)} className="rounded-full p-1 hover:bg-white/20 transition-colors">
                <X className="h-5 w-5" />
              </button>
            </div>
            <form onSubmit={handleCreateReport} className="p-6 space-y-5">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Type de Rapport</label>
                <select
                  value={reportType}
                  onChange={(e) => setReportType(e.target.value)}
                  className="w-full p-2 border border-[#C8A45D/30] rounded-md focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
                >
                  <option value="problème repas">Problème Repas</option>
                  <option value="commentaire produits">Commentaire Produits</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                <textarea
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  className="w-full p-2 border border-[#C8A45D/30] rounded-md focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
                  rows="4"
                  placeholder="Décrivez le problème ou commentaire..."
                  required
                />
              </div>
              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300"
                >
                  Annuler
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-[#00717F] text-white rounded-md hover:bg-[#C8A45D] transition-colors"
                >
                  Soumettre
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Detail Modal */}
      {isDetailModalOpen && selectedReport && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center p-4">
          <div className="bg-white rounded-xl p-0 w-full max-w-md shadow-2xl animate-fadeIn overflow-hidden">
            <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-4 flex justify-between items-center">
              <h3 className="text-xl font-semibold">Détails du Rapport</h3>
              <button onClick={closeDetailModal} className="rounded-full p-1 hover:bg-white/20 transition-colors">
                <X className="h-5 w-5" />
              </button>
            </div>
            <div className="p-6 space-y-5">
              <div className="bg-amber-50 p-3 rounded-lg border border-amber-100">
                <p className="text-sm font-medium text-amber-800 mb-1">Type de Rapport</p>
                <p className="text-gray-900 font-medium">
                  {selectedReport.reportType}
                </p>
              </div>
              <div>
                <p className="text-sm font-medium text-gray-700 mb-1">Description</p>
                <p className="text-gray-900 bg-gray-50 p-3 rounded-lg border border-gray-100">{selectedReport.description}</p>
              </div>

              <div>
                <p className="text-sm font-medium text-gray-700 mb-1">Date de Soumission</p>
                <p className="text-gray-900 flex items-center">
                  <Clock className="h-4 w-4 mr-2 text-gray-500" />
                  {new Date(selectedReport.createdAt).toLocaleString("fr-FR")}
                </p>
              </div>
            </div>
            <div className="border-t border-gray-100 p-4 bg-gray-50 flex justify-end">
              <button
                onClick={closeDetailModal}
                className="px-4 py-2 bg-[#00717F] text-white rounded-md hover:bg-[#00717F] transition-colors duration-150 font-medium"
              >
                Fermer
              </button>
            </div>
          </div>
        </div>
      )}

      <style jsx global>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.2s ease-out forwards;
        }
      `}</style>
    </Layout>
  );
}
